CREATE TABLE q(n);CREATE TABLE r(n,docid);CREATE TRIGGER rq AFTER INSERT ON q WHEN new.n<20 BEGIN INSERT INTO t1(t1) VALUES('merge=1');INSERT INTO t1(t1) VALUES('integrity-check');INSERT INTO r SELECT new.n,docid FROM t1 WHERE t1 MATCH 'zero one two three';INSERT INTO q VALUES(new.n+1);END;INSERT INTO q VALUES(0);